import { escapeHtml } from "../../src/lib/dom.js";
const mi = value => `<mi>${escapeHtml(value)}</mi>`;
const word = value => `<mtext dir="rtl">${escapeHtml(value)}</mtext>`;
const mn = value => `<mn>${escapeHtml(value)}</mn>`;
const mo = value => `<mo>${escapeHtml(value)}</mo>`;
const row = value => `<mrow>${value}</mrow>`;
const power = (base, exponent) => `<msup>${base}${exponent}</msup>`;
const fraction = (top, bottom) => `<mfrac>${row(top)}${row(bottom)}</mfrac>`;
const symbols = values => [...values].map(value => mo(value)).join('<mspace width="0.35em"/>');
const letters = values => [...values].map(value => `<mi mathvariant="normal">${value}</mi>`).join('<mspace width="0.5em"/>');
const x = mi("س"), y = mi("ص"), n = mi("ن");
const square = power(x, mn("٢"));
const parentheses = body => row(mo("(") + body + mo(")"));
const bounds = (operator, bottom, top) => `<munderover>${mo(operator)}${row(bottom)}${top}</munderover>`;
const matrix = rows => `<mtable>${rows.map(cells => `<mtr>${cells.map(cell => `<mtd>${cell}</mtd>`).join("")}</mtr>`).join("")}</mtable>`;

