export function mathSymbolsMarkdown() {
  const content = ['<!-- step-id: math-symbols-preview -->\n<!-- presentation: math-symbols -->', "# تجربة الرموز الرياضية", "صفحة لفحص الأعداد والحروف والرموز والمعادلات قبل إضافة أسئلة الرياضيات. لا توجد أسئلة تقييم في هذه التجربة.",
    `عدد أمثلة العرض: **${MATH_SYMBOL_SAMPLES.length}**.`,
    'مثال داخل النص: `mathml: <math dir="rtl" aria-label="س تربيع زائد ثلاثة"><msup><mi>س</mi><mn>٢</mn></msup><mo>+</mo><mn>٣</mn></math>`.',
  ];
  let previousGroup;
  for (const sample of MATH_SYMBOL_SAMPLES) {
    if (sample.group !== previousGroup) content.push(`## ${sample.group}`);
    content.push('```mathml title="' + sample.title + '"\n' + sample.source + '\n```');
    previousGroup = sample.group;
  }
  return content.join("\n\n");
}
